{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people with refreshment settings and accessible entertainment control.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Provides a cup and plate for one person",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "plate", "saucer"],
        "required_properties": ["holds beverage", "holds food/drinkware"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Controls the television",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["remote control"],
        "required_properties": ["electronic device", "buttons"]
      },
      {
        "id": "surface_for_settings",
        "entity_kind": "REGION",
        "function": "Holds the refreshment settings",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk"],
        "required_properties": ["flat surface", "stable"]
      },
      {
        "id": "seating_area",
        "entity_kind": "REGION",
        "function": "Location where people sit to watch TV",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["chair", "sofa"],
        "required_properties": ["seat", "facing screen"]
      }
    ],
    "functional_relations": [
      {
        "id": "setting_near_seating",
        "relation": "NEAR",
        "participant_roles": ["refreshment_setting", "seating_area"],
        "required": true
      },
      {
        "id": "control_accessible",
        "relation": "ACCESSIBLE_TO",
        "participant_roles": ["entertainment_control", "seating_area"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "arrange_refreshment_settings",
        "operation": "ARRANGE",
        "participant_roles": ["refreshment_setting", "surface_for_settings"],
        "operation_count": 2
      },
      {
        "id": "place_entertainment_control",
        "operation": "PLACE",
        "participant_roles": ["entertainment_control", "surface_for_settings"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {"label": "red_cup", "visual_description": "Red cup on foreground table"},
        {"label": "white_plate", "visual_description": "White plate on foreground table"}
      ],
      "entertainment_control": [
        {"label": "black_remote", "visual_description": "Black remote on foreground table"}
      ],
      "surface_for_settings": [
        {"label": "foreground_table", "visual_description": "Wooden table with items on it"}
      ],
      "seating_area": [
        {"label": "armchair_1", "visual_description": "Armchair near TV"},
        {"label": "armchair_2", "visual_description": "Armchair near TV"}
      ]
    },
    "inspectable_regions": [
      {
        "id": "console_under_tv",
        "label": "Console Table",
        "visual_description": "Wooden table under the TV screen",
        "reason": "Potential storage for entertainment control or additional settings."
      }
    ],
    "inspection_order": [
      "console_under_tv"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
